// ---------------------------------------------------------------------------------------------- helpers
const f = fmt2;   // = String(Math.round(x * 100) / 100), fast (core/math.js)
const f1 = fmt1;
const lerp = (a, b, t) => a + (b - a) * t;
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const wrap = (x, m) => ((x % m) + m) % m;
const D2R = Math.PI / 180;
const rot = ([x, y], a) => { const c = Math.cos(a * D2R), s = Math.sin(a * D2R); return [x * c - y * s, x * s + y * c]; };
const add = (a, b) => [a[0] + b[0], a[1] + b[1]];
const circ = (x, y, r) => `M${f(x - r)} ${f(y)}a${f(r)} ${f(r)} 0 1 0 ${f(2 * r)} 0a${f(r)} ${f(r)} 0 1 0 ${f(-2 * r)} 0Z`;
const ell = (x, y, rx, ry) => `M${f(x - rx)} ${f(y)}a${f(rx)} ${f(ry)} 0 1 0 ${f(2 * rx)} 0a${f(rx)} ${f(ry)} 0 1 0 ${f(-2 * rx)} 0Z`;
const rect = (x, y, w, hh) => `M${f(x)} ${f(y)}h${f(w)}v${f(hh)}h${f(-w)}Z`;
const rrect = (x, y, w, hh, r) => `M${f(x + r)} ${f(y)}h${f(w - 2 * r)}a${f(r)} ${f(r)} 0 0 1 ${f(r)} ${f(r)}v${f(hh - 2 * r)}a${f(r)} ${f(r)} 0 0 1 ${f(-r)} ${f(r)}h${f(-(w - 2 * r))}a${f(r)} ${f(r)} 0 0 1 ${f(-r)} ${f(-r)}v${f(-(hh - 2 * r))}a${f(r)} ${f(r)} 0 0 1 ${f(r)} ${f(-r)}Z`;
const poly = pts => 'M' + pts.map(p => f(p[0]) + ' ' + f(p[1])).join('L') + 'Z';
const line = pts => 'M' + pts.map(p => f(p[0]) + ' ' + f(p[1])).join('L');
function smooth(pts, closed = true, k = 1 / 6) {
  const n = pts.length, g = i => closed ? pts[(i + n) % n] : pts[Math.max(0, Math.min(n - 1, i))];
  let d = `M${f(pts[0][0])} ${f(pts[0][1])}`;
  for (let i = 0; i < (closed ? n : n - 1); i++) {
    const p0 = g(i - 1), p1 = g(i), p2 = g(i + 1), p3 = g(i + 2);
    d += `C${f(p1[0] + (p2[0] - p0[0]) * k)} ${f(p1[1] + (p2[1] - p0[1]) * k)} ${f(p2[0] - (p3[0] - p1[0]) * k)} ${f(p2[1] - (p3[1] - p1[1]) * k)} ${f(p2[0])} ${f(p2[1])}`;
  }
  return d + (closed ? 'Z' : '');
}
const F = (d, fill, o = {}) => d ? h('path', { d, fill, ...o }) : '';
const S = (d, stroke, w, o = {}) => d ? h('path', { d, fill: 'none', stroke, 'stroke-width': w, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', ...o }) : '';
const G = (o, ...k) => h('g', o, ...k);
const smooth01 = x => { const u = clamp(x, 0, 1); return u * u * (3 - 2 * u); };
// catenary-ish sag between two points (quadratic)
const sag = (x0, y0, x1, y1, s) => `M${f(x0)} ${f(y0)}Q${f((x0 + x1) / 2)} ${f((y0 + y1) / 2 + s * 2)} ${f(x1)} ${f(y1)}`;
const sagPt = (x0, y0, x1, y1, s, u) => [lerp(x0, x1, u), lerp(y0, y1, u) + 4 * s * u * (1 - u)];

// ---- glyph outlines (em 100, baseline y = 0) -> path d. mono: DejaVu Sans Mono Bold for the tech labels
function xfD(d, kx, ky, dx, dy) { let i = 0; return d.replace(/-?\d+(?:\.\d+)?/g, m => f1(i++ % 2 === 0 ? +m * kx + dx : +m * ky + dy)); }
function gtext(str, x, y, size, { track = 0, anchor = 'start', sx = 1, mono = false } = {}) {
  const GT = mono ? GLMO : GL;
  const k = size / 100; let w = 0;
  const adv = ch => ch === ' ' ? 30 * k * sx + track : (GT[ch] || GL[ch] ? (GT[ch] || GL[ch])[1] * k * sx + track : 0);
  for (const ch of str) w += adv(ch);
  w -= track;
  let pen = anchor === 'middle' ? x - w / 2 : anchor === 'end' ? x - w : x, d = '';
  for (const ch of str) {
    const g = GT[ch] || GL[ch];
    if (ch !== ' ' && g) d += xfD(g[0], k * sx, k, pen, y);
    pen += adv(ch);
  }
  return { d, w };
}
const txt = (s, x, y, size, o) => gtext(s, x, y, size, o).d;
// vertical CJK column centred on cx, first glyph top at y
const vtxt = (str, cx, y, size, gap = 1.06) => [...str].map((ch, i) => txt(ch, cx, y + (i + 0.86) * size * gap, size, { anchor: 'middle' })).join('');

// ---- neon kit (emissive: the same hue at every hour; signs dim a little at noon through --pb-n-neon)
const NE = {
  mag: '#FF2E88', magK: '#FFD3E7', cyan: '#19E6FF', cyanK: '#D8FBFF', acid: '#C6FF3D', acidK: '#F1FFD0', amber: '#FFB547', amberK: '#FFF0D2',
  red: '#FF3B4E', redK: '#FFD0D6', violet: '#9B5CFF', violetK: '#E4D4FF', white: '#FFF6E8', green: '#3DFF9A', greenK: '#D6FFE9', void: '#07060F',
};
// re-lightable sign colours (a streamed <use> can carry style="--land-c1:…" to swap the neon)
const C1 = `var(--land-c1,${NE.mag})`, C1K = `var(--land-c1k,${NE.magK})`;
const C2 = `var(--land-c2,${NE.cyan})`, C2K = `var(--land-c2k,${NE.cyanK})`;
const C3 = `var(--land-c3,${NE.amber})`, C3K = `var(--land-c3k,${NE.amberK})`;
const NEONV = { style: 'opacity:var(--pb-n-neon)' };
const LITV = { style: 'opacity:var(--pb-n-lampOn)' };
const NOHIT = { 'pointer-events': 'none' };
// neon tube: a wide faint halo, the tube, a pale core
const tube = (d, col, core, w = 1.4, a = 1) => d ? S(d, col, f(w * 3.6), { opacity: f(0.17 * a) }) + S(d, col, f(w), a < 1 ? { opacity: f(a) } : {}) + (core && w >= 1.15 ? S(d, core, f(w * 0.36), a < 1 ? { opacity: f(a) } : {}) : '') : '';
// neon lettering: halo stroke + bright core fill + coloured edge
const ntext = (d, col, core, size) => d ? S(d, col, f(Math.max(1.2, size * 0.16)), { opacity: 0.2 }) + F(d, core) + (size >= 14 ? S(d, col, f(size * 0.03)) : '') : '';
// dark sign box with a neon border (and optional corner brackets)
const at = (x, y, m) => G({ transform: `translate(${f(x)} ${f(y)})` }, m);
// a small standing / sitting figure (deck scale ≈ 16 u/m), feet at (0,0): coat, hood, a visor / phone glow
const person = (coat, glow, sit) => { const DF = 'var(--pb-landDark-far)'; return sit
  ? S('M-3 -2l-1 -8h7M3 -2l1 -6', DF, 1.8) + F('M-5 -9q0 -12 5 -13q5 1 5 13z', coat) + F(circ(0, -25, 3.6), DF) + F('M-4.4 -26q4.4 -6 8.8 0v-2q-4.4 -5 -8.8 0z', coat) + S('M1 -25.6h3', glow, 1.1)
  : S('M-2 0l0.6 -12M2 0l-0.4 -12', DF, 1.9) + F('M-4.6 -11q-0.8 -12 4.6 -13q5.4 1 4.6 13z', coat) + F(circ(0, -28, 3.6), DF) + F('M-4.4 -28.4q4.4 -6.4 8.8 0v-2.6q-4.4 -5.6 -8.8 0z', coat) + S('M1 -28.6h3.2', glow, 1.1) + S('M-4 -16h8', glow, 0.6, { opacity: 0.7 }); };
const nbox = (x, y, w, hh, col, core, o = {}) => F(rrect(x, y, w, hh, o.r ?? 2), o.bg || NE.void, o.bgA ? { opacity: o.bgA } : {}) + tube(rrect(x + 1, y + 1, w - 2, hh - 2, Math.max(0, (o.r ?? 2) - 1)), col, core, o.w ?? 1.2);

