for (const L of Object.values(LAY)) { L.x0 = 800 - L.W / 2; L.x1 = 800 + L.W / 2; }
const tileU = (D, L) => wrap((D - D0) * L.d + L.W / 2, L.W) - L.W / 2;
const LAMP_X = [300, 300 + TILE.roadside / 2];      // lamp posts every 848.23 u (TILE.roadside / 2)
const LAMP_TOP = 462;                                // lamp arm / cable anchor height
const BASE = 752;                                    // roadside objects stand on the pavement here
const SPEC = [18, 432];                              // clear specimen span left of the rider in the hero frame
// wet-road reflection of the pavement (lighting pass): mirror about the pavement ground line, squashed by k (a second,
// longer copy smears the streamed props), clipped to the asphalt band under the translucent road surface
const REFL = (() => { const k = 0.34, k2 = 0.5; return { k, xf: `matrix(1 0 0 ${-k} 0 ${f(BASE * (1 + k))})`, xf2: `matrix(1 0 0 ${-k2} 0 ${f(BASE * (1 + k2) + 3)})`, aTile: 0.9, aStream: 0.55, y0: 772, y1: 874 }; })();
const roadBase = W => F(rect(800 - W / 2 - 3, BASE, W + 6, 152), 'var(--pb-road)');
// (integration, perf) the streak blur is baked into a pattern tile (bakedFilter): as a live filter it was a compositor
// render surface re-blurred every frame. The pattern spans the tile plus a 400 u margin each side, the reflection band
// plus the blur's reach; `REFL_DEFS` collects the pattern defs (added to the module defs in build).
let REFL_DEFS = '', REFL_N = 0;
const reflWrap = (m, W, extra = '') => {
  const b = bakedFilter('land-reflpat' + REFL_N++, [800 - W / 2 - 400, REFL.y0 - 20, W + 800, REFL.y1 - REFL.y0 + 40], 'land-streak', G({ transform: REFL.xf }, m) + extra, { opacity: REFL.aTile });
  REFL_DEFS += b.def;
  // the rect itself is the asphalt band (no clip-path: a path clip made the compositor mask it every frame)
  return b.el.replace(/ y="[^"]*" width="([^"]*)" height="[^"]*"/, ` y="${REFL.y0}" width="$1" height="${REFL.y1 - REFL.y0}"`);
};
// long neon streaks under the tallest sources (their mirror image falls below the asphalt band): lamp bars in every
// tile, the three sign pylons in the hero tile. Blurred with the mirror (same filter).
const lampStreaks = () => LAMP_X.map(x => F(rect(x + 30, REFL.y0, 40, 96), 'url(#land-refA)') + F(rect(x + 42, REFL.y0, 16, 100), 'url(#land-refA)')).join('');
const pylonStreaks = () => F(rect(1502, REFL.y0, 34, 100), 'url(#land-refM)') + F(rect(1512, REFL.y0, 12, 102), 'url(#land-refM)') + F(rect(1384, REFL.y0, 28, 92), 'url(#land-refA)')
  + F(rect(22, REFL.y0, 30, 96), 'url(#land-refC)') + F(rect(32, REFL.y0, 10, 100), 'url(#land-refC)');
// bright-pass bloom over a static tile (lighting pass): a blurred copy of only its brightest neon, laid over the art
// (the bright-pass bloom <use> of the whole tile was dropped in the lighting pass: re-running its wide blur on every new
// raster tile of the scrolling strip cost 2 s dips to 11 fps, and the tubes already glow with stacked strokes)
const mstrip = m => m.replace(/ (?:data-detail|data-size-m|data-ref|id|class)="[^"]*"/g, '');
// Lamp x positions in the roadside layer's coordinates for a given distance (for fx rim-light / other modules).
export function lampPositions(distance, x0 = -500, x1 = 2100) {
  const u = tileU(distance, LAY.roadside), sp = TILE.roadside / 2, out = [];
  for (let x = x0 + wrap(LAMP_X[0] - u - x0, sp); x < x1; x += sp) out.push(x);
  return out;
}
// continuous band drawn as [X0,a] + tagged specimen [a,b] + [b,X1]
const band = (X0, X1, tag, fn, [a, b] = SPEC) => fn(X0, a) + G(tag, fn(a, b)) + fn(b, X1);

// Merge consecutive sibling <path>s that share exactly the same paint attributes (same z-order, same pixels): keeps
// the static tiles to a few hundred nodes.
function mergePaths(m) {
  const re = /<path d="([^"]*)"((?: [a-z-]+="[^"]*")*)\/><path d="([^"]*)"\2\/>/g;
  let prev;
  do { prev = m; m = m.replace(re, (all, a, attrs, b) => (/data-|class=|transform=|clip-path=|url\(/.test(attrs) ? all : `<path d="${a}${b}"${attrs}/>`)); } while (m !== prev);
  return m;
}

// Split long multi-subpath <path>s into ~220 u x-buckets: the rasteriser works per 256 px tile and culls by bounds,
// so compact pieces are far cheaper to paint than one path spanning the whole tile.
function chunkPaths(m, size = 640) {
  return m.replace(/<path d="([^"]*)"((?: [a-z-]+="[^"]*")*)\/>/g, (all, d, attrs) => {
    if (d.length < 400 || /transform=/.test(attrs)) return all;
    const subs = d.split(/(?=M)/); if (subs.length < 2) return all;
    const b = new Map();
    for (const sp of subs) { const x = parseFloat(sp.slice(1)); const k = Math.floor(x / size); b.set(k, (b.get(k) || '') + sp); }
    if (b.size < 2) return all;
    return [...b.values()].map(dd => `<path d="${dd}"${attrs}/>`).join('');
  });
}

